using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Threading;
using LocalLens;
class ExtendedChecks {
 static int count; static string root;
 static void Assert(bool x,string name){if(!x)throw new Exception("FAIL: "+name);count++;Console.WriteLine("PASS: "+name);}
 static void Throws(Action a,string name){bool thrown=false;try{a();}catch{thrown=true;}Assert(thrown,name);}
 static Finding RunCheck(int id,string method,ScanOptions o,params object[] arguments){Finding last=null;var e=new AuditEngine(o,f=>{if(f.Id==id)last=f;},CancellationToken.None);typeof(AuditEngine).GetField("profiles",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(e,new List<string>{Path.Combine(root,"profile")});typeof(AuditEngine).GetMethod("Run",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(e,new object[]{id,(Action)(()=>{try{typeof(AuditEngine).GetMethod(method,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(e,arguments);}catch(TargetInvocationException x){throw x.InnerException;}})});return last;}
 static byte[] Request(){var r=new byte[20];r[1]=1;r[4]=0x21;r[5]=0x12;r[6]=0xa4;r[7]=0x42;for(int i=8;i<20;i++)r[i]=(byte)i;return r;}
 static byte[] Response(byte[] request,byte[] address){var b=new byte[28+address.Length];Buffer.BlockCopy(request,0,b,0,20);b[0]=1;b[1]=1;b[3]=(byte)(8+address.Length);b[21]=0x20;b[23]=(byte)(4+address.Length);b[25]=(byte)(address.Length==4?1:2);for(int i=0;i<address.Length;i++)b[28+i]=(byte)(address[i]^request[4+i]);return b;}
 static void Main(string[] args){root=Path.GetFullPath(args[0]);File.WriteAllText(Path.Combine(root,"bad-browser.json"),"{\"app\":\"unrelated\"}");
  Assert(LocalData.Host("https://user:password@www.example.cn/private?token=hidden")=="www.example.cn","domain extraction excludes credentials, paths and queries");Assert(LocalData.Host("file:///C:/private.txt")=="","non-web URL excluded");Assert(LocalData.ChinaHost("news.example.cn"),"cn domain rule");Assert(!LocalData.ChinaHost("baidu.com.evil.example"),"domain suffix boundary");Assert(!LocalData.Place.IsMatch("FRANCE finance"),"CN token boundary");Assert(LocalData.Place.IsMatch("Shanghai"),"place token");
  Assert(LocalData.Hash(LocalData.Canonical(" b\r\na "))==LocalData.Hash(LocalData.Canonical("a\nb")),"baseline canonical order");Assert(LocalData.Hash("a")!=LocalData.Hash("b"),"baseline changes detected");
  Assert(LocalData.DocumentText(Path.Combine(root,"content","sample.docx")).Contains("北京"),"DOCX XML text read");Throws(()=>LocalData.DocumentText(Path.Combine(root,"content","hostile.docx")),"DOCX external entity / DTD prohibited");Throws(()=>LocalData.DocumentText(Path.Combine(root,"content","oversize.docx")),"compressed oversized XML rejected");Throws(()=>LocalData.ReadBounded(Path.Combine(root,"content","text.txt"),2),"bounded text reader");
  var walk=LocalData.Walk(Path.Combine(root,"content"),2,10,CancellationToken.None);Assert(walk.Capped&&walk.Files.Count==2,"walker reports file cap");var cancelled=new CancellationTokenSource();cancelled.Cancel();Throws(()=>LocalData.Walk(root,10,10,cancelled.Token),"walker cancellation");
  byte[] before=File.ReadAllBytes(Path.Combine(root,"profile","History"));using(var db=new SqliteRead(Path.Combine(root,"profile","History"))){var rows=db.Query("SELECT url FROM urls ORDER BY last_visit_time DESC",10,CancellationToken.None);Assert(rows.Count==3&&rows[0][0].Contains("baidu.com"),"native SQLite read");Throws(()=>db.Query("DELETE FROM urls",10,CancellationToken.None),"SQLite writes rejected");Throws(()=>db.Query("SELECT 1; DROP TABLE urls",10,CancellationToken.None),"SQLite statement chaining rejected");Throws(()=>db.Query("SELECT url FROM urls",10,cancelled.Token),"SQLite cancellation");}Assert(before.SequenceEqual(File.ReadAllBytes(Path.Combine(root,"profile","History"))),"database byte content unchanged");
  var history=RunCheck(34,"BrowserHistory",new ScanOptions{BrowserContent=true});Assert(history.State=="读取失败"&&history.Evidence.Contains("www.baidu.com"),"single-purpose URL table without a real multi-day visits table cannot establish a China user");Assert(!history.Evidence.Contains("superprivate")&&!history.Evidence.Contains("token=hidden"),"history evidence excludes page details");
  var autofill=RunCheck(52,"BrowserAutofill",new ScanOptions{BrowserContent=true});Assert(autofill.State=="发现线索"&&autofill.Evidence.Contains("Beijing"),"autofill country / city allowlist");Assert(!autofill.Evidence.Contains("4111111111111111"),"autofill excludes card fields");
  var ext=RunCheck(66,"Extensions",new ScanOptions());Assert(ext.State=="未发现"&&ext.Evidence.Contains("clipboardRead"),"extension permissions are collected but not called China user evidence");Assert(AuditEngine.SensitivePermission("<all_urls>"),"broad extension permission rule");Assert(!AuditEngine.SensitivePermission("storage"),"ordinary extension permission not elevated");
  var r=Request();Assert(Stun.Parse(Response(r,new byte[]{203,0,113,4}),r)=="203.0.113.4","STUN XOR IPv4");var v6=new byte[16];v6[0]=0x20;v6[1]=1;v6[2]=0x0d;v6[3]=0xb8;v6[15]=1;Assert(Stun.Parse(Response(r,v6),r)=="2001:db8::1","STUN XOR IPv6");var bad=Response(r,new byte[]{1,2,3,4});bad[8]++;Throws(()=>Stun.Parse(bad,r),"STUN transaction mismatch");Throws(()=>Stun.Parse(new byte[3],r),"STUN short packet");bad=Response(r,new byte[]{1,2,3,4});bad[23]=200;Throws(()=>Stun.Parse(bad,r),"STUN attribute length validation");
  var browser=RunCheck(58,"ImportBrowser",new ScanOptions{BrowserReportPath=Path.Combine(root,"browser.json")});Assert(browser.State=="发现线索"&&browser.Evidence.Contains("zh-CN"),"browser JSON import actual environment");var badBrowser=RunCheck(58,"ImportBrowser",new ScanOptions{BrowserReportPath=Path.Combine(root,"bad-browser.json")});Assert(badBrowser.State=="读取失败","wrong browser format rejected");
  var baseFile=Path.Combine(root,"baseline.json");File.WriteAllText(baseFile,"{\"Format\":\"LocalLens Baseline 2\",\"Hashes\":{\"1\":\"wrong\"}}");Throws(()=>Baseline.Load(baseFile),"baseline invalid hash rejected");var b=Baseline.Create(Catalog.Load());Assert(b.Hashes.Count==0,"unchecked findings excluded from baseline");
  var c=Catalog.Load();c[16].State="信息";c[16].Evidence="Name=CN";b=Baseline.Create(c);Assert(b.Hashes.Count==1&&b.Hashes.ContainsKey("17"),"only successful selected findings baselined");
  var report=new AuditReport{Options=new ScanOptions{ContentFolder="privatefolder",BrowserReportPath="private-browser",BaselinePath="private-baseline",ExternalEvidencePath="private-external",OcrExecutable="private-exe"},Findings=c,Snapshot=b};var summary=Exporter.Prepare(report,false);Assert(summary.Snapshot==null&&!summary.Options.ContentFolder.Contains("private")&&!summary.Options.OcrExecutable.Contains("private"),"summary removes new paths and correlatable baseline hashes");
  var offline=RunCheck(8,"NetworkProbes",new ScanOptions{Online=false,Probes=true});Assert(offline.State=="未检测","offline mode blocks all optional network probes");
  var mon=RunCheck(10,"Monitor",new ScanOptions{Online=false,MonitorSeconds=30});Assert(mon.State=="未检测","offline mode blocks monitoring");
  var content=RunCheck(50,"RunContent",new ScanOptions{ContentFolder=Path.Combine(root,"content")});Assert(content.State=="未发现"&&content.Evidence.Contains("读取"),"unowned place mentions are not enough for China-user contact evidence");
  var externalPath=Path.Combine(root,"external.json");File.WriteAllText(externalPath,"{\"format\":\"LocalLens External Evidence 1\",\"records\":[{\"checkId\":56,\"source\":\"Synthetic export\",\"observedAt\":\"2026-10-15T00:00:00Z\",\"countryCode\":\"CN\"}]}");
  var extRecord=RunCheck(56,"ImportExternal",new ScanOptions{ExternalEvidencePath=externalPath},56);Assert(extRecord.State=="发现线索","external country record analyzed with provenance");
  var missingRecord=RunCheck(57,"ImportExternal",new ScanOptions{ExternalEvidencePath=externalPath},57);Assert(missingRecord.State=="需外部记录","absent external class remains unmet");
  File.WriteAllText(externalPath,"{\"format\":\"LocalLens External Evidence 1\",\"records\":[{\"checkId\":56,\"source\":\"Synthetic export\",\"observedAt\":\"2026-10-15T00:00:00Z\",\"countryCode\":\"\"}]}");
  var noCountry=RunCheck(56,"ImportExternal",new ScanOptions{ExternalEvidencePath=externalPath},56);Assert(noCountry.State=="未检测","external record without country cannot clear check");
  var noBase=RunCheck(65,"CompareBaseline",new ScanOptions{AutoDiscoverFiles=false});Assert(noBase.State=="未检测","missing baseline never reported unchanged");
  File.WriteAllText(Path.Combine(root,"bad-browser.json"),"{\"app\":\"LocalLens BrowserCheck 2.0\",\"environment\":{},\"location\":{\"status\":\"returned\",\"latitude\":95,\"longitude\":0}}");
  var badCoord=RunCheck(58,"ImportBrowser",new ScanOptions{BrowserReportPath=Path.Combine(root,"bad-browser.json")});Assert(badCoord.State=="读取失败","out-of-range imported location rejected");
  Console.WriteLine("TOTAL PASSED: "+count);
 }
}
